<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Code Minifier Online','description'=>'Minify HTML, CSS or JavaScript by removing comments and unnecessary whitespace.','url'=>'https://smarttoolz.in/tools/code-minifier/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">CODE MINIFIER</span><h1>Code Minifier</h1><p>Reduce whitespace and comments from code for a compact output.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Code<textarea id="in" rows="14" placeholder="Paste HTML, CSS or JavaScript..."></textarea></label><button id="go" class="tool-btn">Minify Code</button><textarea id="out" rows="14" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy</button></div></section></main><script>(()=>{const i=document.getElementById('in'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let s=i.value.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\/\/[^\n\r]*/g,'').replace(/\s+/g,' ').replace(/\s*([{};,>:])\s*/g,'$1').trim();o.value=s};document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value)})();</script><?php smarttoolz_tool_page_end(); ?>